For more preset capabilities, please refer to the documentation PredefinedMenuItem.

Tip

The menu builder has dedicated methods to add each predefined menu item so you can call .copy() instead of .item(&PredefinedMenuItem::copy(app, None)?).

Change menu status

If you want to change the status of the menu, such as text, icon, or check status, you can set_menu again:

JavaScript

    import {
      Menu,
      CheckMenuItem,
      IconMenuItem,
      MenuItem,
    } from '@tauri-apps/api/menu';
    import { Image } from '@tauri-apps/api/image';

    let currentLanguage = 'en';

    await using check_sub_item_en = await CheckMenuItem.new({
      id: 'en',
      text: 'English',
      checked: currentLanguage === 'en',
      action: () => {
        currentLanguage = 'en';
        check_sub_item_en.setChecked(currentLanguage === 'en');
        check_sub_item_zh.setChecked(currentLanguage === 'cn');
        console.log('English pressed');
      },
    });

    await using check_sub_item_zh = await CheckMenuItem.new({
      id: 'zh',
      text: 'Chinese',
      checked: currentLanguage === 'zh',
      action: () => {
        currentLanguage = 'zh';
        check_sub_item_en.setChecked(currentLanguage === 'en');
        check_sub_item_zh.setChecked(currentLanguage === 'zh');
        check_sub_item_zh.setAccelerator('Ctrl+L');
        console.log('Chinese pressed');
      },
    });

    // Load icon from path
    await using icon = await Image.fromPath('../src/icon.png');
    await using icon2 = await Image.fromPath('../src/icon-2.png');

    await using icon_item = await IconMenuItem.new({
      id: 'icon_item',
      text: 'Icon Item',
      icon: icon,
      action: () => {
        icon_item.setIcon(icon2);
        console.log('icon pressed');
      },
    });

    await using text_item = await MenuItem.new({
      id: 'text_item',
      text: 'Text Item',
      action: () => {
        text_item.setText('Text Item Changed');
        console.log('text pressed');
      },
    });

    await using menu = await Menu.new({
      items: [
        {
          id: 'change menu',
          text: 'change_menu',
          items: [text_item, check_sub_item_en, check_sub_item_zh, icon_item],
        },
      ],
    });

    await menu.setAsAppMenu();

Rust

    // change-menu-status
    #![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]

    use tauri::{
        image::Image,
        menu::{CheckMenuItemBuilder, IconMenuItem, MenuBuilder, MenuItem, SubmenuBuilder},
    };

    fn main() {
        tauri::Builder::default()
            .setup(|app| {
                let check_sub_item_en = CheckMenuItemBuilder::with_id("en", "EN")
                    .checked(true)
                    .build(app)?;

                let check_sub_item_zh = CheckMenuItemBuilder::with_id("zh", "ZH")
                    .checked(false)
                    .build(app)?;

                let text_menu = MenuItem::with_id(
                    app,
                    "change_text",
                    &"Change menu".to_string(),
                    true,
                    Some("Ctrl+Z"),
                )
                .unwrap();

                let icon_menu = IconMenuItem::with_id(
                    app,
                    "change_icon",
                    &"Change icon menu",
                    true,
                    Some(Image::from_bytes(include_bytes!("../icons/icon.png")).unwrap()),
                    Some("Ctrl+F"),
                )
                .unwrap();

                let menu_item = SubmenuBuilder::new(app, "Change menu")
                    .item(&text_menu)
                    .item(&icon_menu)
                    .items(&[&check_sub_item_en, &check_sub_item_zh])
                    .build()?;
                let menu = MenuBuilder::new(app).items(&[&menu_item]).build()?;
                app.set_menu(menu)?;
                app.on_menu_event(move |_app_handle: &tauri::AppHandle, event| {
                    match event.id().0.as_str() {
                        "change_text" => {
                            text_menu
                                .set_text("changed menu text")
                                .expect("Change text error");

                            text_menu
                                .set_text("changed menu text")
                                .expect("Change text error");
                        }
                        "change_icon" => {
                            icon_menu
                                .set_text("changed menu-icon text")
                                .expect("Change text error");
                            icon_menu
                                .set_icon(Some(
                                    Image::from_bytes(include_bytes!("../icons/icon-2.png")).unwrap(),
                                ))
                                .expect("Change icon error");
                        }

                        "en" | "zh" => {
                            check_sub_item_en
                                .set_checked(event.id().0.as_str() == "en")
                                .expect("Change check error");
                            check_sub_item_zh
                                .set_checked(event.id().0.as_str() == "zh")
                                .expect("Change check error");
                            check_sub_item_zh.set_accelerator(Some("Ctrl+L"))
                            .expect("Change accelerator error");
                        }
                        _ => {
                            println!("unexpected menu event");
                        }
                    }
                });

                Ok(())
            })
            .run(tauri::generate_context!())
            .expect("error while running tauri application");
    }

Prevent JavaScript menu leaks

There're a few gotchas you should be aware of when using the JavaScript menu APIs, mainly because JavaScript does not have any way to run cleanup code when an object is being removed by garbage collection:

• The menus will not clean up automatically unless close is called or closed by await using after the binding variable goes out of scope.

• You should close the menu items you got e.g. from Menu.get, the await using syntax makes it easier, for example: await using status = menu.get('status') Be careful with APIs that can return a Menu such as Menu.setAsAppMenu, you'll need to close them when you're done with them or if you don't plan to use them.

• You should close the menu resource whenever you don't need to access it in JavaScript anymore.

For example:

Manual close

    const copy = await PredefinedMenuItem.new({ item: 'Copy' });
    const menu = await Menu.new({ items: [copy] });
    // `copy` is now managed by the `menu` and the JavaScript resource reference can be closed
    await copy.close();

    const prev = await menu.setAsAppMenu();
    // `menu` is now set as the app menu, we can close the JavaScript resource reference
    await menu.close();
    // We don't plan to use the previously set menu, close it here.
    await prev?.close();

await using

    await using copy = await PredefinedMenuItem.new({ item: 'Copy' });
    await using menu = await Menu.new({ items: [copy] });
    await using prev = await menu.setAsAppMenu();

Tip

Think about it this way, all the menus in JavaScript are added references to the actual menus, and you need to release all the references to release a menu.

Autostart

Automatically launch your application at system startup.

Supported Platforms

This plugin requires a Rust version of at least 1.90

 Platform   Level   Notes

 windows   Full support

 linux   Full support

 macos   Full support

 android   No support

 ios   No support

Setup

Install the autostart plugin to get started.

Automatic

Use your project's package manager to add the dependency:

{' '}

npm

    npm run tauri add autostart

yarn

    yarn run tauri add autostart

pnpm

    pnpm tauri add autostart

deno

    deno task tauri add autostart

bun

    bun tauri add autostart

cargo

    cargo tauri add autostart

Manual

• Run the following command in the src-tauri folder to add the plugin to the project's dependencies in Cargo.toml:

    cargo add tauri-plugin-autostart --target 'cfg(any(target_os = "macos", windows, target_os = "linux"))'

• Modify lib.rs to initialize the plugin:

    #[cfg_attr(mobile, tauri::mobile_entry_point)]
    pub fn run() {
        tauri::Builder::default()
            .setup(|app| {
                #[cfg(desktop)]
                app.handle().plugin(tauri_plugin_autostart::init(tauri_plugin_autostart::MacosLauncher::LaunchAgent, Some(vec!["--flag1", "--flag2"]) /* arbitrary number of args to pass to your app */));
                Ok(())
            })
            .run(tauri::generate_context!())
            .expect("error while running tauri application");
    }

• You can install the JavaScript Guest bindings using your preferred JavaScript package manager:

npm

    npm install @tauri-apps/plugin-autostart

yarn

    yarn add @tauri-apps/plugin-autostart

pnpm

    pnpm add @tauri-apps/plugin-autostart

deno

    deno add npm:@tauri-apps/plugin-autostart

bun

    bun add @tauri-apps/plugin-autostart

Usage

The autostart plugin is available in both JavaScript and Rust.

JavaScript

    import { enable, isEnabled, disable } from '@tauri-apps/plugin-autostart';
    // when using `"withGlobalTauri": true`, you may use
    // const { enable, isEnabled, disable } = window.__TAURI__.autostart;

    // Enable autostart
    await enable();
    // Check enable state
    console.log(`registered for autostart? ${await isEnabled()}`);
    // Disable autostart
    disable();

Rust

    #[cfg_attr(mobile, tauri::mobile_entry_point)]
    pub fn run() {
        tauri::Builder::default()
            .setup(|app| {
                #[cfg(desktop)]
                {
                    use tauri_plugin_autostart::MacosLauncher;
                    use tauri_plugin_autostart::ManagerExt;

                    app.handle().plugin(tauri_plugin_autostart::init(
                        MacosLauncher::LaunchAgent,
                        Some(vec!["--flag1", "--flag2"]),
                    ));

                    // Get the autostart manager
                    let autostart_manager = app.autolaunch();
                    // Enable autostart
                    let _ = autostart_manager.enable();
                    // Check enable state
                    println!("registered for autostart? {}", autostart_manager.is_enabled().unwrap());
                    // Disable autostart
                    let _ = autostart_manager.disable();
                }
                Ok(())
            })
            .run(tauri::generate_context!())
            .expect("error while running tauri application");
    }

Permissions

By default all potentially dangerous plugin commands and scopes are blocked and cannot be accessed. You must modify the permissions in your capabilities configuration to enable these.

See the Capabilities Overview for more information and the step by step guide to use plugin permissions.

    {
      "permissions": [
        ...,
        "autostart:allow-enable",
        "autostart:allow-disable",
        "autostart:allow-is-enabled"
      ]
    }

Default Permission

This permission set configures if your application can enable or disable auto starting the application on boot.

Granted Permissions

It allows all to check, enable and disable the automatic start on boot.

This default permission set includes the following:

• allow-enable

• allow-disable

• allow-is-enabled

Permission Table

 Identifier   Description

 autostart:allow-disable   Enables the disable command without any pre-configured scope.

 autostart:deny-disable   Denies the disable command without any pre-configured scope.

 autostart:allow-enable   Enables the enable command without any pre-configured scope.

 autostart:deny-enable   Denies the enable command without any pre-configured scope.

 autostart:allow-is-enabled   Enables the is_enabled command without any pre-configured scope.

 autostart:deny-is-enabled   Denies the is_enabled command without any pre-configured scope.

Biometric

Prompt the user for biometric authentication on Android and iOS.

Supported Platforms

This plugin requires a Rust version of at least 1.90

